create table if not exists public.menu_limits(id text primary key, hits integer not null, expires timestamptz not null);
alter table public.menu_limits enable row level security;
revoke all on public.menu_limits from anon,authenticated;
create or replace function public.menu_rate(p_key text,p_max integer) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$
declare c integer;begin
 insert into menu_limits values(p_key,1,now()+interval '1 minute') on conflict(id) do update set hits=case when menu_limits.expires<now() then 1 else menu_limits.hits+1 end,expires=case when menu_limits.expires<now() then now()+interval '1 minute' else menu_limits.expires end returning hits into c;
 delete from menu_limits where expires<now()-interval '1 hour';return c<=p_max;end $$;
revoke all on function public.menu_rate(text,integer) from public,anon,authenticated;
grant execute on function public.menu_rate(text,integer) to service_role;
